public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null) return result;
    int n = nums.length;
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    backtrack(nums, used, current, result);
    return result;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> result) {
    if (current.size() == nums.length) {
        result.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, result);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to limit substring generation
    String shortest = null;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (shortest == null || s.length() < shortest.length()) {
            shortest = s;
        }
    }
    if (shortest == null || shortest.isEmpty()) {
        return 0;
    }
    int shortestLen = shortest.length();
    // Try lengths from longest to shortest
    for (int len = shortestLen; len >= 1; len--) {
        // Generate all substrings of this length from the shortest string
        for (int start = 0; start <= shortestLen - len; start++) {
            String sub = shortest.substring(start, start + len);
            String rev = new StringBuilder(sub).reverse().toString();
            boolean allContain = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    allContain = false;
                    break;
                }
            }
            if (allContain) {
                return len;
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // DFS stack
                java.util.Deque<int[]> stack = new java.util.ArrayDeque<>();
                stack.push(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] pos = stack.pop();
                    int cr = pos[0];
                    int cc = pos[1];
                    for (int d = 0; d < 8; d++) {
                        int nr = cr + dr[d];
                        int nc = cc + dc[d];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.push(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

