public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0 || k <= 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k; // handle negative numbers
        freq[rem]++;
    }
    // remainder 0 must have even count
    if (freq[0] % 2 != 0) {
        return false;
    }
    // if k is even, remainder k/2 must have even count
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) {
            return false;
        }
    }
    // check other remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // already handled k even case
            continue;
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.ArrayList<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        int u = e[0];
        int v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    int[] stack = new int[n];
    int top = 0;
    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int orderSize = 0;

    stack[top++] = 0;
    parent[0] = -1;
    while (top > 0) {
        int node = stack[--top];
        order[orderSize++] = node;
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack[top++] = nei;
            }
        }
    }

    boolean[] subtreeHasApple = new boolean[n];
    int total = 0;
    for (int i = orderSize - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nei : graph[node]) {
            if (nei != parent[node] && subtreeHasApple[nei]) {
                has = true;
                total += 2;
            }
        }
        subtreeHasApple[node] = has;
    }
    return total;
}

public String sortString(String s) {
    TreeMap<Character, Integer> map = new TreeMap<>();
    for (char c : s.toCharArray()) {
        map.put(c, map.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!map.isEmpty()) {
        // Step 1: pick smallest
        char cur = map.firstKey();
        result.append(cur);
        if (--map.get(cur) == 0) map.remove(cur);
        // Step 2: increasing sequence
        while (true) {
            Character next = map.higherKey(cur);
            if (next == null) break;
            cur = next;
            result.append(cur);
            if (--map.get(cur) == 0) map.remove(cur);
        }
        if (map.isEmpty()) break;
        // Step 4: pick largest
        cur = map.lastKey();
        result.append(cur);
        if (--map.get(cur) == 0) map.remove(cur);
        // Step 5: decreasing sequence
        while (true) {
            Character next = map.lowerKey(cur);
            if (next == null) break;
            cur = next;
            result.append(cur);
            if (--map.get(cur) == 0) map.remove(cur);
        }
    }
    return result.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) dp[i] = new java.util.HashSet<>();
    dp[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                dp[k].add(sum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    // dp[0] = 0, dp[1] = 0
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    int curr = 0;
    for (int i = 2; i <= n; i++) {
        curr = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = curr;
    }
    return curr;
}

