public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) return 0;
    long curMax = nums[0];
    long curMin = nums[0];
    long maxSum = nums[0];
    long minSum = nums[0];
    for (int i = 1; i < nums.length; i++) {
        long val = nums[i];
        curMax = Math.max(val, curMax + val);
        maxSum = Math.max(maxSum, curMax);
        curMin = Math.min(val, curMin + val);
        minSum = Math.min(minSum, curMin);
    }
    long answer = Math.max(maxSum, -minSum);
    return (int) answer;
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    int[] fibs = new int[50]; // 50 is enough for k up to 10^9
    int size = 0;
    fibs[size++] = 1;
    fibs[size++] = 1;
    while (true) {
        int next = fibs[size - 1] + fibs[size - 2];
        if (next > k) break;
        fibs[size++] = next;
    }
    // Greedy subtraction
    int count = 0;
    int remaining = k;
    for (int i = size - 1; i >= 0; i--) {
        if (fibs[i] <= remaining) {
            remaining -= fibs[i];
            count++;
        }
        if (remaining == 0) break;
    }
    return count;
}

public int kthFactor(int n, int k) {
    ArrayList<Integer> factors = new ArrayList<>();
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrtN; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    Collections.sort(factors);
    if (k <= factors.size()) {
        return factors.get(k - 1);
    } else {
        return -1;
    }
}

public String makeGood(String s) {
