private int dfs(int pos, String s, java.util.Set<String> used) {
    if (pos == s.length()) {
        return 0;
    }
    int max = 0;
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!used.contains(sub)) {
            used.add(sub);
            int count = 1 + dfs(end, s, used);
            if (count > max) {
                max = count;
            }
            used.remove(sub);
        }
    }
    return max;
}

public int minOperations(String[] logs) {
