public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        // Update twos with bits that have appeared twice
        twos |= ones & num;
        // Update ones with bits that have appeared once
        ones ^= num;
        // Bits that have appeared three times are removed from ones and twos
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }
    Queue<Long> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low) {
            result.add((int) num);
        }
        long lastDigit = num % 10;
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
            }
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower = n % factor;
        long cur = (n / factor) % 10;
        long higher = n / (factor * 10);
        count += higher * factor;
        if (cur == 1) {
            count += lower + 1;
        } else if (cur > 1) {
            count += factor;
        }
        factor *= 10;
    }
    return (int) count;
}

